import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  ChartBarIcon,
  ExclamationTriangleIcon,
  GlobeAltIcon,
  DocumentTextIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon
} from '@heroicons/react/24/outline';
import AlertsPanel from './AlertsPanel';
import DMARCReportsPanel from './DMARCReportsPanel';
import DNSStatusPanel from './DNSStatusPanel';
import apiService from '../services/api';
import { useNotification } from '../contexts/NotificationContext';

const Dashboard = () => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const { showNotification } = useNotification();

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      const data = await apiService.getDashboardData();
      setDashboardData(data);
    } catch (error) {
      console.error('Error loading dashboard data:', error);
      showNotification('Error al cargar los datos del dashboard', 'error');
    } finally {
      setLoading(false);
    }
  };

  const StatCard = ({ title, value, icon: Icon, color, description, link }) => {
    const colorClasses = {
      blue: 'bg-blue-500 text-white',
      green: 'bg-green-500 text-white',
      yellow: 'bg-yellow-500 text-white',
      red: 'bg-red-500 text-white',
      gray: 'bg-gray-500 text-white'
    };

    const content = (
      <div className="card">
        <div className="card-body">
          <div className="flex items-center">
            <div className={`flex-shrink-0 p-3 rounded-lg ${colorClasses[color] || colorClasses.blue}`}>
              <Icon className="h-6 w-6" />
            </div>
            <div className="ml-4 flex-1">
              <p className="text-sm font-medium text-gray-500">{title}</p>
              <p className="text-2xl font-semibold text-gray-900">{value}</p>
              {description && (
                <p className="text-sm text-gray-600 mt-1">{description}</p>
              )}
            </div>
          </div>
        </div>
      </div>
    );

    return link ? (
      <Link to={link} className="block hover:shadow-lg transition-shadow duration-200">
        {content}
      </Link>
    ) : (
      content
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="spinner h-12 w-12 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="py-6">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          {/* Header */}
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Dashboard DMARC</h1>
            <p className="mt-2 text-gray-600">
              Monitoreo y gestión de la seguridad de correo electrónico
            </p>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4 mb-8">
            <StatCard
              title="Dominios Activos"
              value={dashboardData?.total_domains || 0}
              icon={GlobeAltIcon}
              color="blue"
              description="Dominios configurados"
              link="/domains"
            />
            <StatCard
              title="Alertas Activas"
              value={dashboardData?.active_alerts || 0}
              icon={ExclamationTriangleIcon}
              color={dashboardData?.active_alerts > 0 ? 'red' : 'green'}
              description="Requieren atención"
              link="/alerts"
            />
            <StatCard
              title="Reportes DMARC"
              value={dashboardData?.total_reports || 0}
              icon={DocumentTextIcon}
              color="green"
              description="Últimos 30 días"
              link="/reports"
            />
            <StatCard
              title="Tasa de Cumplimiento"
              value={`${dashboardData?.compliance_rate || 0}%`}
              icon={ChartBarIcon}
              color={dashboardData?.compliance_rate >= 80 ? 'green' : dashboardData?.compliance_rate >= 60 ? 'yellow' : 'red'}
              description="Promedio DMARC"
            />
          </div>

          {/* Quick Actions */}
          <div className="mb-8">
            <h2 className="text-lg font-medium text-gray-900 mb-4">Acciones Rápidas</h2>
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <Link
                to="/wizard"
                className="btn-primary text-center py-3 px-4 rounded-lg shadow-sm hover:shadow-md transition-shadow duration-200"
              >
                <AcademicCapIcon className="h-5 w-5 mx-auto mb-2" />
                Asistente de Configuración
              </Link>
              <Link
                to="/domains/new"
                className="btn-secondary text-center py-3 px-4 rounded-lg shadow-sm hover:shadow-md transition-shadow duration-200"
              >
                <GlobeAltIcon className="h-5 w-5 mx-auto mb-2" />
                Agregar Dominio
              </Link>
              <Link
                to="/reports"
                className="btn-secondary text-center py-3 px-4 rounded-lg shadow-sm hover:shadow-md transition-shadow duration-200"
              >
                <DocumentTextIcon className="h-5 w-5 mx-auto mb-2" />
                Ver Reportes
              </Link>
              <Link
                to="/settings"
                className="btn-secondary text-center py-3 px-4 rounded-lg shadow-sm hover:shadow-md transition-shadow duration-200"
              >
                <CogIcon className="h-5 w-5 mx-auto mb-2" />
                Configuración
              </Link>
            </div>
          </div>

          {/* Main Content Grid */}
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2 xl:grid-cols-3">
            {/* Alerts Panel */}
            <div className="lg:col-span-1">
              <div className="card">
                <div className="card-header">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-medium text-gray-900">Alertas Recientes</h3>
                    <Link
                      to="/alerts"
                      className="text-sm text-primary-600 hover:text-primary-500"
                    >
                      Ver todas
                    </Link>
                  </div>
                </div>
                <div className="card-body p-0">
                  <AlertsPanel limit={5} showHeader={false} />
                </div>
              </div>
            </div>

            {/* DMARC Reports Panel */}
            <div className="lg:col-span-1">
              <div className="card">
                <div className="card-header">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-medium text-gray-900">Reportes DMARC</h3>
                    <Link
                      to="/reports"
                      className="text-sm text-primary-600 hover:text-primary-500"
                    >
                      Ver todos
                    </Link>
                  </div>
                </div>
                <div className="card-body p-0">
                  <DMARCReportsPanel limit={5} showHeader={false} />
                </div>
              </div>
            </div>

            {/* DNS Status Panel */}
            <div className="lg:col-span-2 xl:col-span-1">
              <div className="card">
                <div className="card-header">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-medium text-gray-900">Estado DNS</h3>
                    <Link
                      to="/domains"
                      className="text-sm text-primary-600 hover:text-primary-500"
                    >
                      Ver detalles
                    </Link>
                  </div>
                </div>
                <div className="card-body p-0">
                  <DNSStatusPanel compact={true} />
                </div>
              </div>
            </div>
          </div>

          {/* System Status */}
          {dashboardData?.system_status && (
            <div className="mt-8">
              <div className="card">
                <div className="card-header">
                  <h3 className="text-lg font-medium text-gray-900">Estado del Sistema</h3>
                </div>
                <div className="card-body">
                  <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
                    <div className="flex items-center">
                      {dashboardData.system_status.api_status === 'healthy' ? (
                        <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2" />
                      ) : (
                        <XCircleIcon className="h-5 w-5 text-red-500 mr-2" />
                      )}
                      <span className="text-sm text-gray-600">API: {dashboardData.system_status.api_status}</span>
                    </div>
                    <div className="flex items-center">
                      {dashboardData.system_status.database_status === 'healthy' ? (
                        <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2" />
                      ) : (
                        <XCircleIcon className="h-5 w-5 text-red-500 mr-2" />
                      )}
                      <span className="text-sm text-gray-600">Base de datos: {dashboardData.system_status.database_status}</span>
                    </div>
                    <div className="flex items-center">
                      {dashboardData.system_status.celery_status === 'healthy' ? (
                        <CheckCircleIcon className="h-5 w-5 text-green-500 mr-2" />
                      ) : (
                        <ClockIcon className="h-5 w-5 text-yellow-500 mr-2" />
                      )}
                      <span className="text-sm text-gray-600">Tareas: {dashboardData.system_status.celery_status}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
